_HERE = _P(__file__).resolve().parent; S.OUT = _HERE; (_HERE / "data").mkdir(exist_ok=True)
_GUARD = {p: _hl.md5(open(p, "rb").read()).hexdigest() for p in _glob.glob(str(_HERE.parent / "Fig*.p*"))}
from cns_style import INK, SLATE, GREY, LIGHT, PAPER, IMMUNE, STROMA, MACRO, fmt_p

R = S.RES
W, H = 180, 234                           # v41 230; +4 mm for the larger type
